package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.minecraft.world.phys.shapes.CollisionContext;

/** Loaded-only endpoint discovery. Disk preparation pauses motion; it never reports an asynchronous job as refusal. */
final class NativeGearPayloadService {
    static volatile java.util.function.BiConsumer<NativeGearEntity,String> endpointProbe;
    private static void probe(NativeGearEntity owner,String step){var observer=endpointProbe;if(observer!=null)observer.accept(owner,step);}
    private static boolean endpoint(double progress){return progress==0||progress==1;}
    private static BlockPos tip(NativeGearEntity owner){try{return nativeCell(owner,owner.getBlockPos().offset(NativeGearOrientation.vector(owner.mount(),new BlockPos(0,-owner.assembly().columnHeight(),0))));}catch(IllegalArgumentException fractional){return null;}}

    static boolean beforeTick(NativeGearEntity owner){if(owner.assembly()==null||owner.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.NONE||!(owner.getLevel() instanceof ServerLevel level))return true;if(NativeGearJournal.busy(owner))return false;if(owner.progress()==0&&owner.payload()==null&&!owner.hasStoredSections()&&owner.definition().kind==NativeGearDefinition.Kind.ROTATING){try{var plan=NativeGearLandingPlan.capture(owner);if(plan!=null){var status=NativeGearJournal.adopt(owner,owner.actor(),plan);if(status==NativeGearJournal.Status.PENDING)owner.journalWaiting("Preparing landing attachment");return false;}}catch(RuntimeException refused){owner.journalFailure(java.util.Objects.toString(refused.getMessage(),"Landing attachment refused"));return false;}}var payload=owner.payload();boolean moving=owner.progress()!=(owner.target()?1:0);if(!moving){if(payload!=null&&!payload.materialized()&&endpoint(owner.progress()))return materialize(owner,level,payload);return true;}if(owner.blocked())return true;if(payload!=null&&!payload.materialized())return true;if(!endpoint(owner.progress())){if(payload==null&&owner.sections()==null)return true;owner.journalFailure("Attachment ownership is unavailable between endpoints");return false;}try{
        BlockPos source=tip(owner);if(source==null)return true;if(!NativeGearFormation.loaded(level,source)){owner.journalWaiting("Load the complete attachment first");return false;}var state=level.getBlockState(source);
        var selected=owner.columns().size()>1?NativeGearJoined.selected(owner,cell->nativeCell(owner,cell)):state.isAir()||ownSection(owner,level,source)?Set.<BlockPos>of():Set.of(source);
        if(selected.isEmpty()){if(owner.sections()!=null)return restoreEmpty(owner,level);if(payload!=null)owner.journalPayload(null);owner.journalWaiting("");return true;}
        NativeGearPushing.preflight(owner);return capture(owner,level,selected);
        }catch(RuntimeException failure){var reason=Objects.toString(failure.getMessage(),"Attachment preparation failed");if(owner.canPushBlocks()&&owner.settings().pushBlocks())owner.pushFailure(reason);else owner.journalFailure(reason);return false;}}
    private static BlockPos nativeCell(NativeGearEntity owner,BlockPos construction){
        var local=NativeGearOrientation.inverse(owner.mount(),construction.subtract(owner.getBlockPos()));var point=NativeGearPayload.frame(owner,owner.progress()).point(local.getX()+.5,local.getY()+.5,local.getZ()+.5);double x=point.x-.5,y=point.y-.5,z=point.z-.5;
        if(Math.abs(x-Math.rint(x))+Math.abs(y-Math.rint(y))+Math.abs(z-Math.rint(z))>1e-8)throw new IllegalArgumentException("Joined attachment endpoint is not on the native grid");return owner.getBlockPos().offset((int)Math.rint(x),(int)Math.rint(y),(int)Math.rint(z));
    }
    private static boolean capture(NativeGearEntity owner,ServerLevel level,Set<BlockPos> selected){
        var ready=NativeGearJournal.readyToPrepare(owner);if(ready!=NativeGearJournal.Status.READY){if(ready==NativeGearJournal.Status.REFUSED)owner.journalFailure(NativeGearJournal.error(owner));else owner.journalWaiting("Waiting for attachment journal capacity");return false;}
        var actor=owner.actor();if(actor==null){owner.journalWaiting("Waiting for the owner to return");return false;}
        selected=NativeObserverCapture.complete(level,selected);
        var cells=new ArrayList<NativeGearSnapshot.Cell>();var shapes=new ArrayList<List<AABB>>();var after=new LinkedHashMap<BlockPos,NativeGearSnapshot.Cell>();
        for(var source:selected){
            if(!NativeGearFormation.loaded(level,source))throw new IllegalArgumentException("Load the complete attachment first");var state=level.getBlockState(source);
            if(!level.mayInteract(actor,source)||!actor.mayUseItemAt(source,Direction.UP,actor.getMainHandItem()))throw new IllegalArgumentException("You cannot move the attachment here");if(NativeObserverCapture.breakBlocked(actor,level,source,state))throw new IllegalArgumentException("A protection rule prevented moving the attachment");
            if(state.getBlock() instanceof FallingBlock||state.getBlock() instanceof TntBlock||!state.getFluidState().isEmpty()||state.getDestroySpeed(level,source)<0)throw new IllegalArgumentException("Unsupported dynamic arm attachment");
            boolean building=state.getBlock() instanceof com.vandorlabs.neoforge.shape.NativeProgrammableSlab||state.getBlock() instanceof com.vandorlabs.neoforge.shape.NativeProgrammableStairs||state.getBlock()==com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get();if(!building&&!(state.getBlock() instanceof SlabBlock)&&!(state.getBlock() instanceof StairBlock)&&!state.hasBlockEntity()&&!state.isCollisionShapeFullBlock(level,source))throw new IllegalArgumentException("Use supported solid blocks on the arm platform");
            cells.add(NativeGearSnapshot.capture(level,source,false));var boxes=state.getCollisionShape(level,source,CollisionContext.empty()).toAabbs();shapes.add(boxes.isEmpty()?List.of(new AABB(0,0,0,1,1,1)):boxes);after.put(source,new NativeGearSnapshot.Cell(source,Blocks.AIR.defaultBlockState(),null));
        }
        if(!NativeObserverCapture.complete(level,selected).equals(selected))throw new IllegalArgumentException("Observer ownership changed during protection checks");
        var captured=new NativeGearPayload(UUID.randomUUID(),cells,shapes,owner.progress(),false,NativeGearPayload.frame(owner,owner.progress()));
        if(owner.sections()!=null)for(var section:owner.sections().cells()){if(!selected.contains(section.pos)&&!level.getBlockState(section.pos).isAir())throw new IllegalArgumentException("Clear the stored arm section before extending");after.put(section.pos,section);}
        captured.view(owner.getBlockPos(),level.registryAccess());var status=NativeGearJournal.start(owner,actor,List.copyOf(after.values()),captured,null);if(status==NativeGearJournal.Status.PENDING)owner.journalWaiting("Preparing attachment ownership");return false;
    }
    private static boolean materialize(NativeGearEntity owner,ServerLevel level,NativeGearPayload payload){probe(owner,"query");if(owner.cachedEndpointFailure(payload)!=null)return true;try{if(NativeGearJournal.readyToPrepare(owner)!=NativeGearJournal.Status.READY)return false;final java.util.List<NativeGearSnapshot.Cell> endpoint;try{probe(owner,"build");endpoint=payload.endpoint(owner,owner.progress());}catch(IllegalArgumentException structural){var reason=Objects.toString(structural.getMessage(),"Attachment remains captured at this angle");owner.rememberEndpointFailure(payload,reason);owner.journalWaiting(reason);return true;}if(endpoint.isEmpty()){owner.rememberEndpointFailure(payload,"");return true;}var actor=owner.actor();if(actor==null){owner.journalWaiting("Waiting for the owner to return");return false;}var displaced=new ArrayList<NativeGearSnapshot.Cell>();for(var cell:endpoint){if(!NativeGearFormation.loaded(level,cell.pos)){owner.journalWaiting("Load the complete native endpoint first");return false;}if(!level.getBlockState(cell.pos).isAir()||level.getBlockEntity(cell.pos)!=null){if(!NativeGearStoredSections.canStore(owner,cell.pos))throw new IllegalArgumentException("The native attachment endpoint is occupied");displaced.add(NativeGearStoredSections.capture(owner,cell.pos));}}var nativePayload=payload.materialized(owner,owner.progress(),endpoint);nativePayload.view(owner.getBlockPos(),level.registryAccess());var status=NativeGearJournal.start(owner,actor,endpoint,nativePayload,NativeGearStoredSections.merge(owner.sections(),displaced));if(status==NativeGearJournal.Status.PENDING)owner.journalWaiting("Publishing the native attachment endpoint");return false;}catch(IllegalArgumentException unsupported){owner.journalWaiting(Objects.toString(unsupported.getMessage(),"Attachment remains captured at this angle"));return true;}catch(RuntimeException failure){owner.journalFailure(Objects.toString(failure.getMessage(),"Native endpoint publication failed"));return false;}}
    private static boolean ownSection(NativeGearEntity owner,ServerLevel level,BlockPos pos){if(!owner.members().contains(pos)||owner.sections()!=null&&owner.sections().at(pos)!=null)return false;var member=NativeGearFormation.at(level,pos);return member!=null&&member.mount()==owner.mount()&&owner.getBlockPos().equals(member.owner())&&member.controllerEntity()==owner;}
    private static boolean restoreEmpty(NativeGearEntity owner,ServerLevel level){if(NativeGearJournal.readyToPrepare(owner)!=NativeGearJournal.Status.READY)return false;var actor=owner.actor();if(actor==null){owner.journalWaiting("Waiting for the owner to return");return false;}for(var cell:owner.sections().cells())if(!NativeGearFormation.loaded(level,cell.pos)||!level.getBlockState(cell.pos).isAir()){owner.journalWaiting("Clear the stored arm section before extending");return false;}NativeGearJournal.start(owner,actor,owner.sections().cells(),null,null);return false;}
    private NativeGearPayloadService(){}
}
